INSERT INTO `categories` VALUES (1,'Các sản phẩm ăn liền có hạn sử dụng rõ ràng như mì gói, mì ly, cháo ăn liền, phở/bún ăn liền, xúc xích đóng gói...','https://i.pinimg.com/1200x/2d/ab/ed/2dabedd5f6e9ec32d5d0740af97f9448.jpg','Đồ ăn liền đóng gói'),(2,'Các loại bánh kẹo, chocolate, thạch, pudding, bánh quy và đồ ngọt đóng gói có hạn sử dụng...','https://i.pinimg.com/1200x/68/0a/e8/680ae807d3b340551d0a34dbc2d10f87.jpg','Bánh kẹo & Đồ ngọt'),(3,'Nước ngọt, trà, cà phê, nước ép, sữa và các loại đồ uống đóng chai/lon/hộp có hạn sử dụng...','https://i.pinimg.com/736x/ef/23/31/ef2331cf59e7f003682c2b0221510799.jpg','Đồ uống '),(4,'Thực phẩm chế biến và đóng gói sẵn như đồ hộp, thực phẩm túi, sản phẩm khô, ngũ cốc và các mặt hàng có hạn sử dụng...','https://i.pinimg.com/736x/c0/46/68/c04668023077b07df9660cebb33e6791.jpg','Thực phẩm đóng gói'),(5,'Các món ăn vặt đóng gói như snack, khoai tây chiên, rong biển, bánh mặn, hạt và đồ nhâm nhi có hạn sử dụng...','https://i.pinimg.com/1200x/b8/9b/06/b89b066f3f3da16e0516d0614721faf2.jpg','Ăn vặt'),(6,'Gia vị, nước chấm, sốt, hạt nêm, bột nấu ăn và nguyên liệu phụ trợ nấu nướng có hạn sử dụng...','https://i.pinimg.com/736x/f7/8b/64/f78b64ce916c1670fddf59f7d95d8079.jpg','Gia vị & Nguyên liệu');
/*!40000 ALTER TABLE `categories` ENABLE KEYS */;
