CREATE TABLE `products` (
  `product_id` bigint NOT NULL AUTO_INCREMENT,
  `active` bit(1) DEFAULT NULL,
  `approval_status` varchar(255) DEFAULT NULL,
  `created_at` datetime(6) DEFAULT NULL,
  `current_price` double DEFAULT NULL,
  `deal_end_time` datetime(6) DEFAULT NULL,
  `deal_price` double DEFAULT NULL,
  `deal_start_time` datetime(6) DEFAULT NULL,
  `deleted` bit(1) DEFAULT NULL,
  `description` text,
  `expiry_date` datetime(6) DEFAULT NULL,
  `image_url` varchar(255) DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `original_price` double DEFAULT NULL,
  `pickup_deadline` datetime(6) DEFAULT NULL,
  `product_type` varchar(255) DEFAULT NULL,
  `rejection_reason` text,
  `stock_quantity` int DEFAULT NULL,
  `updated_at` datetime(6) DEFAULT NULL,
  `version` bigint DEFAULT NULL,
  `category_id` bigint DEFAULT NULL,
  `created_by` bigint DEFAULT NULL,
  `store_id` bigint DEFAULT NULL,
  `manufacturing_date` datetime(6) DEFAULT NULL,
  `suggested_at` datetime(6) DEFAULT NULL,
  `suggested_discount` double DEFAULT NULL,
  `suggested_price` double DEFAULT NULL,
  `manually_stopped` bit(1) DEFAULT NULL,
  PRIMARY KEY (`product_id`),
  KEY `FKog2rp4qthbtt2lfyhfo32lsw9` (`category_id`),
  KEY `FKl0lce8i162ldn9n01t2a6lcix` (`created_by`),
  KEY `FKgcyffheofvmy2x5l78xam63mc` (`store_id`),
  CONSTRAINT `FKgcyffheofvmy2x5l78xam63mc` FOREIGN KEY (`store_id`) REFERENCES `stores` (`store_id`),
  CONSTRAINT `FKl0lce8i162ldn9n01t2a6lcix` FOREIGN KEY (`created_by`) REFERENCES `users` (`user_id`),
  CONSTRAINT `FKog2rp4qthbtt2lfyhfo32lsw9` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=147 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
