ULL,_binary '','Combo Bánh Đa Cua + Trà Sữa Trân Châu siêu tiết kiệm','2026-06-15 23:59:59.000000','/uploads/05fbe8e7c7ed3003a51f2a587755f7d5.jpg','Combo Ăn Trưa BN',55000,NULL,'COMBO',NULL,21,'2026-06-20 18:11:33.868772',NULL,1,3,3,NULL,NULL,NULL,NULL,NULL),(40,_binary '\0','APPROVED','2026-06-08 00:34:30.639384',0,NULL,NULL,NULL,_binary '','2 chai nước mắm cao cấp cốt nhĩ tôm Đầu Bếp Tôm 18 độ đạm 500ml đậm đà, thơm ngon tự nhiên từ tôm thật, nước mắm Đầu Bếp Tôm cốt nhĩ tôm là dòng nước mắm cao cấp với nguồn nguyên liệu chất lượng, đảm bảo an toàn cho sức khỏe người tiêu dùng.','2024-06-10 23:59:59.000000','/uploads/1f213f4239d2064f404cef52a4657ed8.webp','2 chai nước mắm cao cấp cốt nhĩ tôm Đầu Bếp Tôm 18 độ đạm 500ml',69000,NULL,'SPECIFIC_DEAL',NULL,10,'2026-06-20 18:52:47.986916',1,6,3,3,NULL,NULL,NULL,NULL,NULL),(41,_binary '\0','APPROVED','2026-06-08 00:35:42.832050',0,NULL,NULL,NULL,_binary '','Nước mắm của thương hiệu nước mắm Đầu Bếp Tôm được chế biến từ những con tôm tươi được tuyển chọn. Thùng 15 chai nước chấm Đầu Bếp Tôm 800ml được làm từ cốt tôm thật, với vị mặn dịu và ngọt nhẹ, giúp tăng thêm hương vị cho các món ăn hằng ngày.','2026-06-14 23:59:59.000000','/uploads/812f560ca226a0b674d8e1b7d3ccf17b.webp','Thùng 15 chai nước chấm Đầu Bếp Tôm chai 800ml',175000,NULL,'SPECIFIC_DEAL',NULL,10,'2026-06-20 18:52:52.516110',6,6,3,3,NULL,NULL,NULL,NULL,NULL),(42,_binary '\0','APPROVED','2026-06-15 00:41:05.055215',295000,NULL,NULL,NULL,_binary '','Thương hiệu sữa chua Yomost mang đến những dòng sản phẩm được làm từ sữa chua lên men tự nhiên, kết hợp với trái cây thơm ngon, cung cấp nhiều loại dinh dưỡng cần thiết và protein cho cơ thể. Thùng 48 hộp sữa chua uống hương cam YoMost 170ml đóng thùng tiện lợi và có hương cam thơm lừng.','2026-07-31 23:59:59.000000','/uploads/632c41d371075083ae26fa9507a6de11.webp','Thùng 48 hộp sữa chua uống hương cam YoMost 170ml',295000,NULL,'SPECIFIC_DEAL',NULL,5,'2026-06-22 22:27:26.501386',5,3,3,3,'2026-01-15 00:00:00.000000','2026-06-19 03:01:24.111265',25,221250,NULL),(43,_binary '\0','APPROVED','2026-06-15 01:20:59.640228',70400,NULL,NULL,NULL,_binary '','Là loại nước ngọt được nhiều người yêu thích đến từ thương hiệu nước ngọt Pepsi nổi tiếng thế giới với hương vị thơm ngon, sảng khoái. Nước ngọt Pepsi không calo 24 lon 320ml với lượng gas lớn sẽ giúp bạn xua tan mọi cảm giác mệt mỏi, căng thẳng, sản phẩm không calo lành mạnh, tốt cho sức khỏe','2026-06-28 23:59:59.000000','/uploads/3913ffccefeee0fc4c1f630822517af1.webp','Thùng 24 lon nước ngọt Pepsi không calo 320ml',176000,NULL,'SPECIFIC_DEAL',NULL,6,'2026-06-22 22:27:20.164860',10,NULL,3,3,'2026-01-15 00:00:00.000000','2026-06-22 17:05:27.440640',80,35200,NULL),(44,_binary '\0','APPROVED','2026-06-15 01:22:30.702954',0,NULL,NULL,NULL,_binary '','Bánh hạt dinh dưỡng Pikpop Mè Rang là món ăn vặt thực dưỡng kết hợp giữa gạo lứt giòn tan và các loại hạt cao cấp (bí xanh, hạnh nhân, óc chó), mang vị béo bùi đặc trưng của mè và mặn nhẹ từ muối hồng Himalaya, hoàn hảo cho chế độ ăn kiêng hoặc bổ sung năng lượng nhanh.','2026-06-30 23:59:59.000000','/uploads/e7e53c6b525af6287196eae770c90971.webp','Bánh hạt dinh dưỡng mè rang FnV PIKPOP hộp 60g',57000,NULL,'SPECIFIC_DEAL',NULL,0,'2026-06-30 23:11:06.292406',16,2,3,3,'2026-02-07 00:00:00.000000','2026-06-29 09:43:04.301914',80,11400,NULL),(45,_binary '\0','APPROVED','2026-06-15 01:23:44.519648',36000,NULL,NULL,NULL,_binary '','Bánh quy thơm, giòn kích thích vị giác. Bánh yến mạch socola hạnh nhân Munchy\'s Oat Krunch gói192g hấp dẫn với những miếng socola hạnh nhân và yến mạch hòa quyện trong bánh. Bánh quy Munchy\'s được nhập khẩu từ Malaysia chất lượng cao','2026-06-20 23:59:59.000000','/uploads/122de9dd7a201bfab1c1d5bea41b98d7.webp','Bánh yến mạch socola hạnh nhân Munchy\'s Oat Krunch gói 192g',36000,NULL,'SPECIFIC_DEAL',NULL,5,'2026-06-30 23:11:11.436676',1,2,3,3,'2026-05-01 00:00:00.000000','2026-06-15 01:50:39.129273',60,14400,NULL),(46,_binary '\0','APPROVED','2026-06-15 01:24:53.296234',49000,NULL,NULL,NULL,_binary '','Chất lượng với rong biển thơm ngon, tẩm gia vị rất đậm đà. Rong biển trộn cơm truyền thống Tohogenkai gói 50g có thể ăn trực hoặc ăn với cơm rất ngon. Rong biển Tohogenkai kết hợp với cơm ăn chất lượng trong hỗn hợp rong biển khiến cho món ăn trở nên hấp dẫn và không bị ngán.','2026-06-30 23:59:59.000000','/uploads/9083d1f97ff46108a1285fa9a3df7c9c.webp','Rong biển trộn cơm vị truyền thống Tohogenkai gói 50g',49000,NULL,'SPECIFIC_DEAL',NULL,1,'2026-06-30 23:11:16.561395',8,NULL,3,3,'2026-02-15 00:00:00.000000','2026-06-22 05:27:31.296979',60,19600,NULL),(47,_binary '\0','APPROVED','2026-06-15 01:25:54.344007',22000,NULL,NULL,NULL,_binary '','Rong nho Tasami chất lượng, an toàn được nhiều người yêu thích. Rong nho Tasami xốt mè rang gói 35g dùng để ăn kèm với các món ăn khác, giúp bữa ăn gia đình của bạn thêm tròn vị và đậm đà. Rong nho có nguồn gốc xuất xứ rõ ràng, an toàn cho người sử dụng. ','2026-07-12 23:59:59.000000','/uploads/d2d2d2e8496ec688aa9576bddd53b8c0.webp','Rong nho Tasami xốt mè rang gói 35g',22000,NULL,'SPECIFIC_DEAL',NULL,2,'2026-06-30 23:11:20.787110',16,4,3,3,'2026-03-14 00:00:00.000000','2026-06-30 10:26:49.033519',40,13200,NULL),(48,_binary '\0','APPROVED','2026-06-15 08:06:23.402626',0,NULL,NULL,NULL,_binary '','Bánh sandwich sốt bơ phô mai chà bông Orion C\'est Bon gói 147g (6 cái) là loại bánh bông lan ăn sáng bổ dưỡng, bánh bông lan Orion sẽ là nguồn cung cấp năng lượng và làm dịu cơn đói với sốt bơ phô mai chà bông thơm béo mặn ngọt lạ miệng, hấp dẫn.','2026-06-30 23:59:59.000000','/uploads/8bd54933e1d3f8f558d1f6c288d7a851.webp','Bánh sandwich sốt bơ phô mai chà bông Orion C\'est Bon gói 147g (6 cái)',36000,NULL,'SPECIFIC_DEAL',NULL,7,'2026-06-30 23:11:24.625052',16,2,3,3,'2026-02-15 00:00:00.000000','2026-06-29 16:43:06.796318',80,7200,NULL),(49,_binary '\0','APPROVED','2026-06-15 08:07:52.920985',265000,NULL,NULL,NULL,_binary '','Thùng 24 hộp sữa hạt ít đường Vinamilk 9 loại hạt 180ml giàu d