0000,NULL,NULL,NULL,_binary '','Khoác lên mình thiết kế dạng lon nhôm bắt mắt phối hợp cùng các chi tiết đã được tối giản tối đa nhằm mang lại nét trẻ trung, năng động, hiện đại và tinh khiết cho sản phẩm mới của Aquafina. Nước giải khát có ga Aquafina Soda 320ml thùng 24 lon phù hợp để pha chế nên các loại cocktail, soda mix,…','2026-07-12 23:59:59.000000','/uploads/0e96eaa246f7a253cc29704b9a0293c1.webp','Thùng 24 lon nước giải khát có ga Aquafina Soda 320ml',180000,NULL,'SPECIFIC_DEAL',NULL,10,'2026-06-22 22:59:07.777621',1,3,3,3,'2026-01-01 00:00:00.000000','2026-06-15 09:12:12.052568',40,108000,NULL),(57,_binary '\0','APPROVED','2026-06-15 10:36:31.926370',553000,NULL,NULL,NULL,_binary '','Combo thùng 24 lon Redbull Thái kẽm vitamin 250ml và Redbull 250ml mang đến sự kết hợp hoàn hảo giữa công thức bổ sung vi chất và năng lượng bứt phá. Thưởng thức combo Redbull giúp đập tan mệt mỏi, nạp nhanh năng lượng, tăng tỉnh táo tức thì. Mua nguyên thùng siêu tiện lợi, cực đã khi ướp lạnh.','2026-07-12 23:59:59.000000','/uploads/456e0b05063f4d943c2d96e7ce9f779f.webp','24 lon nước tăng lực Redbull Thái kẽm và vitamin 250ml và 24 lon nước tăng lực Redbull 250ml',553000,NULL,'SPECIFIC_DEAL',NULL,5,'2026-06-22 22:27:07.897927',6,3,3,3,'2025-12-29 00:00:00.000000','2026-06-20 15:12:47.122284',40,331800,NULL),(58,_binary '\0','APPROVED','2026-06-15 10:48:12.069961',44000,NULL,NULL,NULL,_binary '','Từng thỏi bánh gạo dẻo dai thấm đều trong nước sốt cay cay ngọt ngọt tạo nên hương vị đặc chưng đậm nét Hàn Quốc. Bánh gạo Yopokki vị cay ngọt 140g với dạng ly nhỏ gọn tiện lợi, chế biến đơn giản, nhanh chóng chỉ cần nước sôi là đã có ngay bữa ăn liền thơm ngon và hấp dẫn\r\n','2026-06-28 23:59:59.000000','/uploads/6321343878f7f69963c7ed5db5dad005.webp','Bánh gạo Yopokki vị cay ngọt ly 140g',44000,NULL,'SPECIFIC_DEAL',NULL,8,'2026-06-30 23:11:36.486837',4,1,3,3,'2026-01-28 00:00:00.000000','2026-06-18 13:38:37.613200',60,17600,NULL),(59,_binary '\0','APPROVED','2026-06-15 10:57:54.